from collections import deque


def max_sliding_window(nums, k):
    window = deque()   # indices, values strictly decreasing front to back
    out = []

    for i, n in enumerate(nums):
        # Dominance: anything smaller at the back is finished.
        while window and nums[window[-1]] <= n:
            window.pop()
        window.append(i)

        # Expiry: the front may have slid out of range.
        if window[0] <= i - k:
            window.popleft()

        # Only emit once the first full window exists.
        if i >= k - 1:
            out.append(nums[window[0]])

    return out

