function maxSlidingWindow(nums, k) {
  const window = []; // indices, values strictly decreasing front to back
  const out = [];

  for (let i = 0; i < nums.length; i += 1) {
    // Dominance: anything smaller at the back is finished.
    while (window.length > 0 && nums[window[window.length - 1]] <= nums[i]) {
      window.pop();
    }
    window.push(i);

    // Expiry: the front may have slid out of range.
    if (window[0] <= i - k) window.shift();

    if (i >= k - 1) out.push(nums[window[0]]);
  }

  return out;
}

std::vector<long long> maxSlidingWindow(std::vector<long long> nums, long long k) {
    std::deque<std::size_t> window;  // indices, values decreasing front to back
    std::vector<long long> out;

    for (std::size_t i = 0; i < nums.size(); ++i) {
        // Dominance: anything smaller at the back is finished.
        while (!window.empty() && nums[window.back()] <= nums[i]) window.pop_back();
        window.push_back(i);

        // Expiry: the front may have slid out of range.
        if ((long long)window.front() + k <= (long long)i) window.pop_front();

        if ((long long)i >= k - 1) out.push_back(nums[window.front()]);
    }

    return out;
}
